/* @lc app=leetcode id=1928 lang=kotlin */ class Solution { fun minCost(maxTime: Int, edges: Array<IntArray>, passingFees: IntArray): Int = passingFees.size.let { n -> (1..maxTime).fold(listOf(IntArray(n) { Int.MAX_VALUE }.also { it[0] = passingFees[0] })) { dp, t -> dp + IntArray(n) { Int.MAX_VALUE }.also { nw -> edges.forEach { (a, b, w) -> if (w <= t) listOf(a to b, b to a).forEach { (u, v) -> if (dp[t - w][u] != Int.MAX_VALUE) nw[v] = minOf(nw[v], dp[t - w][u] + passingFees[v]) } } } }.minOf { it[n - 1] }.let { if (it == Int.MAX_VALUE) -1 else it } } }